-- Runs every gold load procedure: dimensions first, then the
-- tables that read them. Step 4 of the daily pipeline.
-- Generated by `python -m fde render` from every gold spec. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [ops].[RunGoldLoads]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    EXEC [distribution].[LoadDimAgent] @LoadDate = @LoadDate, @LoadStepID = @LoadStepID;
    EXEC [sales].[LoadFactNewBusiness] @LoadDate = @LoadDate, @LoadStepID = @LoadStepID;
END
GO
